   &= a + b + c + 3 \sqrt[3]{ab} \left( \sqrt[3]{a} + \sqrt[3]{b} \right) - 3 \sqrt[3]{ac} \left( \sqrt[3]{a} + \sqrt[3]{c} \right) - 3 \sqrt[3]{bc} \left( \sqrt[3]{b} + \sqrt[3]{c} \right) + 3 \sqrt[3]{abc} \\
   &= a + b + c + 3 \sqrt[3]{ab} \left( \sqrt[3]{a} + \sqrt[3]{b} - \sqrt[3]{c} \right) - 3 \sqrt[3]{c} \left( \sqrt[3]{ab} - \sqrt[3]{ac} - \sqrt[3]{bc} \right) + 3 \sqrt[3]{abc} \\
   &= a + b + c + 3 \sqrt[3]{ab} \left( \sqrt[3]{a} + \sqrt[3]{b} - \sqrt[3]{c} \right) + 3 \sqrt[3]{c} \left( \sqrt[3]{a} + \sqrt[3]{b} - \sqrt[3]{c} \right) \left( \sqrt[3]{ab} + \sqrt[3]{ac} + \sqrt[3]{bc} \right) + 3 \sqrt[3]{abc} \\
